actions.script:
if (!/^[0-9a-f]{32}$/i.test(String(traceId))) throw new Error('Invalid trace id')
from = from || 'now-7d'; thru = thru || 'now'
const result = ec.service.sync().name('org.moqui.report.ReportServices.query#Documents').parameters({
    datasetId:'otel_spans',queryString:'trace_id:'+traceId,from,thru,pageSize:1000,sort:['start_nano','span_id']
}).call()
spans = (result.hits || []).map(hit => hit.body || {})
spanLimitReached = result.total > spans.length
const stamp = value => { const date = new Date(/^\d+$/.test(String(value)) ? Number(value) : value); return Number.isNaN(date.getTime()) ? String(value || '') : date.toISOString() }
// The flame graph of the same trace: span-name paths and their self time, computed on the server.
const flame = ec.service.sync().name('org.moqui.report.ReportServices.run#Query').parameters({
    query:{datasetId:'otel_spans',mode:'flame',queryString:'trace_id:'+traceId,from,thru}
}).call()
flameFrame = (flame.frames || [])[0] || {fields:[]}
spanItems = spans.map(span => ({time:stamp(span.start),title:span.name,
    text:span.status_code+' · '+(Number(span.duration_nano)/1000000).toFixed(2)+' ms · '+span.span_id,kind:span.status_code==='ERROR'?'error':'info'}))
